<template>
  <DocumentLock
    :document_version="document_version"
    :trigger_document_lock="trigger_document_lock"
    :doc_id="docId"
    @setTriggerDocumentLock="setTriggerDocumentLock"
  />

  <InvoiceDuplicateLock
    v-if="!trigger_document_lock && isInvoiceDuplicate"
    :doc_id="docId"
    :doc_type="docType"
    :doc_status="docStatus"
    @setInvoiceDuplicateStatus="setInvoiceDuplicateStatus"
  />

  <MessageBanner
    v-if="isReadOnly && !trigger_document_lock && !isInvoiceDuplicate"
    :message="error_message"
    :messageCategoryClass="bannerBg"
  />

  <SubHeader
    name="field_validation"
    :onSearch="false"
    :label="$t('field_validation')"
    :show_expiry_alert="true"
  />

  <div class="row highlighted-back q-pl-md top-back-button-bar">
    <div class="row full-width">
      <!-- <div class="secondary-c-text text-h6" :style="'width:' + imageFieldSplitter + '%'">
        <div>
          <f-btn appearance="tertiary" data-cy="dashboard" @click="goToDashboard" >
            <Icon icon="mdi:arrow-left-circle" width="20" height="20" />
            <label class="primary-dashboard" >{{ $t('dashboard') }}</label >
          </f-btn>
        </div>
      </div> -->
      <div class="q-pt-sm q-pl-md filename-container" :style="'width:' + (100 - imageFieldSplitter) + '%'" >
        <timeSpentTimer v-if="hasApiData" />
      </div>
    </div>

    <div class="col-auto q-pt-sm filename-container" v-if="false">
      <timeSpentTimer v-if="hasApiData" />

      <div class="image_control_panel float-right" v-if="false">
        <AISeverityLevel />
      </div>
    </div>
  </div>

  <div v-if="!doc_fetch_error" class="row q-pl-md" id="validation_view">
    <div :class="rightSectionClass" id="right_section" ref="right_section">
      <q-splitter
        :limits="[30, 80]"
        v-model="imageFieldSplitter"
        class="scroll-area-height-validation"
        @update:model-value="splitterChanged()"
      >
        <template v-slot:before>
          <div class="q-pr-sm q-pa-sm">
            <div class="full-width medi-fields-content-height">
              <template v-if="hasApiData">
                <FieldsView
                  ref="fieldsView"
                  :page="page"
                  :isReadOnly="isReadOnly"
                  :isPanelSection="false"
                  :renderOpenWindoIcon="true"
                  @onFieldLoad="onFieldLoad"
                  @getImageDetails="getImageDetails"
                  @setSplitterModel="setSplitterModel"
                  @handleScroll="removeOverlayandLines"
                  @showConnectionFromField="showConnectionFromField"
                  @refreshCanvasAfterSelection="refreshCanvasAfterSelection"
                  @removeOldMapiingsAndDrawNew="removeOldMapiingsAndDrawNew"
                  @enableOrDisableExportButton="enableOrDisableExportButton"
                  @checkFieldInvalid="checkFieldInvalid"
                />
              </template>
            </div>
          </div>
        </template>

        <template v-slot:after>
          <q-resize-observer @resize="onResize" :debounce="0" />
          <div>
            <div id="image_container">
              <div
                class="full-width"
                id="image_scrolle"
                style="position: relative"
              >
                <q-splitter
                  horizontal
                  :limits="[0, 100]"
                  :disable="!isExtenedPanel"
                  v-model="splitterModel"
                  class="scroll-area-height-img"
                  :after-class="isExtenedPanel ? 'q-pa-xs' : 'q-px-sm'"
                  before-class="q-pa-sm img-magnifier-container"
                  :separator-class="isExtenedPanel ? 'q-ma-sm' : 'q-ma-sm'"
                  @update:model-value="removeOverlayandLines"
                >
                  <template v-slot:before>
                    <div class="img-magnifier-glass"></div>

                    <AnnotationView
                      ref="child_comp"
                      v-if="field_view_mode == 'annotate'"
                      :enableEditing="enable_editing"
                      :cropUrl="image + '?' + tokenQueryParam"
                      :width="imageWidth"
                      :selectFont="selectFont"
                      :selectFontSize="selectFontSize"
                      :selectColor="selectColor"
                      screenmode="annotate"
                    />

                    <div id="validate-container" class="">
                      <img
                        class="screenshot"
                        :src="image + '?' + tokenQueryParam"
                        :width="imageWidth"
                        id="screenshot"
                        ref="screenshot"
                        draggable="false"
                        @load="
                          imageLoaded = true;
                          getImageDetails();
                        "
                      />

                      <svg
                        :width="imageWidth"
                        :height="imageHeight"
                        :viewBox="viewBox"
                        id="draw"
                        ref="draw"
                        xmlns="http://www.w3.org/2000/svg"
                        style="height: auto; border-bottom: 5px dotted"
                      >
                        <rect
                          id="marquee"
                          ref="marquee"
                          x="450"
                          y="420"
                          width="150"
                          height="150"
                        />
                        <g id="boxes" ref="boxes"></g>
                      </svg>
                    </div>
                  </template>

                  <template v-slot:separator>
                    <q-btn
                      v-if="isExtenedPanel"
                      :disable="!isExtenedPanel"
                      round
                      unelevated
                      size="xs"
                      icon="swap_vert"
                      class="panel-expand-button highlighted-back z-index-1"
                      @click="toggleSplitter()"
                    />
                  </template>

                  <template v-slot:after>
                    <div
                      class="full-width"
                      v-if="renderComponent && hasApiData"
                      id="afterSlot"
                    >
                      <template
                        v-for="(groupObj, groupIndex) in formLayout"
                        :key="`div-${groupIndex}`"
                      >
                        <div
                          class="display-inline-block"
                          v-if="groupObj.is_panel_section_group === true"
                          :style="'width:' + getElementWidth(groupObj) + '%'"
                        >
                          <div
                            class="row q-pl-sm q-pr-sm"
                            v-if="groupObj.title"
                          >
                            <div
                              class="col-sm-12 col-md-12 col-lg-12 secondary-c-text text-h6 q-pb-md text-weight-bold"
                            >
                              {{ groupObj.title }}
                            </div>
                          </div>
                          <div class="full-width">
                            <template
                              v-for="(element, elementIndex) in groupObj.rows"
                              :key="`div-${elementIndex}`"
                            >
                              <div
                                v-if="!isFieldHidden(element)"
                                class=""
                                :style="
                                  'width:' + getElementWidth(element) + '%'
                                "
                              >
                                <component
                                  :is="element.fieldType"
                                  :currentField="element"
                                  :isReadOnly="isReadOnly"
                                  :fieldName="element.name"
                                  :groupIndex="groupIndex"
                                  :itemIndex="elementIndex"
                                  @updateModel="
                                    ($refs['fieldsView'] as any)?.updateModel
                                  "
                                  @inputClicked="
                                    ($refs['fieldsView'] as any)
                                      ?.showConnectionFromField
                                  "
                                  @inputValueChanges="
                                    ($refs['fieldsView'] as any)
                                      ?.onInputValueChanges
                                  "
                                  @applyFuzzySearch="
                                    ($refs['fieldsView'] as any)
                                      ?.applyFuzzySearchWrapper
                                  "
                                >
                                </component>
                              </div>
                            </template>
                          </div>
                        </div>
                      </template>
                    </div>
                  </template>
                </q-splitter>
              </div>
            </div>

            <!-- right action bar -->

            <!-- <span v-if="docType == 'INVOICE'">

                        <q-btn flat id="document_flow" data-cy="docflow"  class="pr-6 pl-6" @click="toFlowScreen(this.$route.params.id as string)" >
                          <img width="24" height="24" src="flow.svg" />
                          <q-tooltip>{{ $t('document_flow') }}</q-tooltip>
                        </q-btn>
                      </span> -->

            <div class="column absolute-right q-ml-auto justify-between right-action-bar back-white" >
              <q-btn
                v-if="showScrollUpButton"
                icon="keyboard_arrow_up"
                flat
                class="validation-view-scroll-down icon-grey"
                @click="onScrollUp"
              />
              <div class="action-bar-items" id="validation_bar_content">
                <q-btn
                  id="bar_magnify_glas"
