                >
                  <Icon icon="mdi:monitor-multiple" width="20" height="20" />
                  <q-tooltip style="white-space: nowrap">
                    {{ $t('open_image') }} <br />
                    {{ $t('CHROME_ONLY') }}
                  </q-tooltip>
                </q-btn>

                <keyboardShortcutInfoBtn />

                <q-separator class="separator-space" />

                <TaskBtn @btnClicked="toggleSideBar('tasks')" />

                <SidebarActionButtons
