                  "
                >
                  <Icon icon="mdi:chat" width="20" height="20" class="icon-grey" />
                  <q-tooltip style="white-space: nowrap">{{
                    $t('deactivate_mode')
                  }}</q-tooltip>
                </q-btn>

                <q-btn
                  id="bar_annotation_mode"
                  flat
