                />

                    <q-btn id="bar_ocr_view" :disabled="record.extraction_method === 'ELECTRONIC_DOCUMENT'" flat class="validation-view-button icon-grey" @click="viewOCRDocument">
                      <Icon icon="mdi:text-recognition" width="20" height="20" />
                      <q-tooltip style="white-space: nowrap;">{{ $t('ocr_view') }}</q-tooltip>
                    </q-btn>

                <q-separator class="separator-space" />
                <q-btn
                  icon="adb"
                  flat
                  class="validation-view-button icon-grey"
