                  >
                </q-btn>

                <autoTesting @setApiData="setApiData" />

                <q-btn
                  id="bar_create_ticket"
                  flat
                  class="validation-view-button font-size-15 icon-grey"
                  @click="toggleSideBar('support')"
                >
                  <Icon icon="mdi:ticket" width="20" height="20" />
                  <q-tooltip style="white-space: nowrap">{{
                    $t('create_ticket')
                  }}</q-tooltip>
                </q-btn>

                <q-btn
                  id="bar_script_logs"
