                  <q-tooltip style="white-space: nowrap">{{
                    $t('barcode_assignment')
                  }}</q-tooltip>
                </q-btn>

                <q-btn
                  v-if="user_settings['SHOW_EXTRACTION_INSIGHTS']"
                  flat
                  id="validation_extraction_insights"
                  class="validation-view-button v-p-0 font-size-15 icon-grey"
                  :class="{ 'sidebar-active': current_sidebar === 'extraction_insights' }"
                  @click="toggleSideBar('extraction_insights')"
                  data-testid="extraction-insights-toggle"
                >
                  <Icon icon="mdi:scale-balance" width="20" height="20" />
                  <q-tooltip style="white-space: nowrap">{{
                    $t('extraction_insights.tooltip')
                  }}</q-tooltip>
                </q-btn>

                <q-btn
                  id="bar_more_settings"
