                  <Icon icon="mdi:dots-horizontal" width="20" height="20" />
                  <q-tooltip style="white-space: nowrap">{{ $t('more_options') || 'More options' }}</q-tooltip>
                  <q-menu
                    transition-show="jump-down"
                    transition-hide="jump-up"
