                        <q-item-section>{{
                          $t('split_document_btn_tooltip')
                        }}</q-item-section>
                      </q-item>

                      <!-- <q-item clickable v-if="docType == 'INVOICE'" @click="improveDocuments()" :to="'/dashboard'">
                            <q-item-section avatar class="list-avatar">
                              <q-icon name="img:/images/improve_document.svg" size="xs" class="invert" style="font-size: 22px"/>
                            </q-item-section>
                            <q-item-section>{{$t('improve_document_btn_tooltip')}}</q-item-section>
                          </q-item> -->

                      <q-item
                        clickable
                        v-if="docType == 'INVOICE'"
                        @click="toFlowScreen($route.params.id as string)"
                      >
                        <q-item-section avatar class="list-avatar">
                          <Icon icon="mdi:transit-connection-variant" width="16" height="16" />
                        </q-item-section>
                        <q-item-section>{{
                          $t('document_flow')
                        }}</q-item-section>
                      </q-item>

                      <q-separator inset />

                      <q-item clickable @click="goToLayoutTemplate()">
                        <q-item-section avatar class="list-avatar">
                          <Icon icon="mdi:view-module" width="16" height="16" />
                        </q-item-section>
                        <q-item-section>Go to Layout Template</q-item-section>
                      </q-item>

                      <q-separator inset />
                    </q-list>
                    <template v-if="record.tfidf_id">
                      <TfidfPreferenceControl
                        :tfidf_id="record.tfidf_id"
                        @restartDocument="restartDocument"
                        :docId="docId"
                        :isReadOnly="isReadOnly"
                      />
                    </template>
                  </q-menu>
                </q-btn>
              </div>
              <div class="action-bar-bottom">
                <q-btn
                  v-if="showScrollDownButton"
                  icon="keyboard_arrow_down"
                  flat
                  class="validation-view-scroll-down icon-grey"
                  @click="onScrollDown"
                />
                <q-separator class="q-mb-sm" />
                <div class="q-my-auto">
                  <q-btn
                    flat
                    class="validation-view-button icon-grey"
                    @click="toggleSideBar('pages')"
                  >
                    <Icon icon="mdi:file-multiple" width="20" height="20" />
                    <q-tooltip>
                      {{ currentPage() }} / {{ images.length }}
                    </q-tooltip>
                  </q-btn>
                </div>
                <q-input
                  outlined
                  dense
                  v-model="page"
                  class="validation-view-input"
                  @update:model-value="
                    (val: any) => {
                      quickActionClicked(val);
                    }
                  "
                  @blur="validatePageNumber"
                ></q-input>
                <span class="validation-view-button q-pt-md">{{
                  lastPageItem
                }}</span>
                <div>
                  <q-btn
                    :disable="page == 1"
                    icon="keyboard_arrow_up"
                    flat
                    class="validation-view-page-button icon-grey"
                    @click="movePageDown"
                  />
                  <q-btn
                    :disable="page == lastPageItem"
                    icon="keyboard_arrow_down"
                    flat
                    class="validation-view-page-button icon-grey"
                    @click="movePageUp"
                  />
                </div>
              </div>
            </div>
          </div>
