              Check Check
            </q-drawer> -->
        </template>
      </q-splitter>
    </div>

    <div :class="[sidebarWidthClass, { hidden: current_sidebar === '' }]" id="left_section" ref="left_section">
      <div class="scrolle-y full-height" v-if="current_sidebar == 'pages'" >
        <div class="row justify-center q-pl-md q-pr-md q-pt-md">
          <span class="secondary-c-text text-h6 text-weight-bold">
            {{ $t('page_number_text') }}
          </span>
        </div>

        <div class="row">
          <div class="page-numbers center-inner">
            {{ currentPage() }}/{{ images.length }}
          </div>
        </div>

        <div class="full-width pages-section-padding row justify-center height-100vh-180px">
          <img
            v-for="(imageMoc, index) in images"
            :data-id="index"
            :key="index"
            :src="baseUrl + '/' + imageMoc.path + '?' + tokenQueryParam"
            class="q-pa-xs shadow-5 max-width-120 q-ma-sm cursor-pointer"
            :class="index === page - 1 ? 'active' : ''"
            style="height: 160px"
            @click="imageclicked"
          />
        </div>
      </div>
      <div class="scrolle-y full-height full-width" v-if="current_sidebar == 'support'">
        <supportForm />
