      </div>
      <SidebarPanel
        :currentSidebar="current_sidebar"
        :docId="docId"
        @close="toggleSideBar(current_sidebar)"
      />
    </div>
  </div>
  <div class="row bg-grey-2 q-pl-md q-pr-md q-pb-md" v-else>
    <ErrorDocumentView />
  </div>

  <Loader />

