  <!-- OVERLAY DIALOG START -->
  <div class="">
    <q-dialog
      v-model="textConfirmation"
      persistent
      transition-show="scale"
      transition-hide="scale"
    >
      <q-card style="width: 440px">
        <q-toolbar class="secondary-toolbar">
          <q-toolbar-title
            ><span class="text-weight-bold">
              {{ $t('confirmation') }}
            </span>
          </q-toolbar-title>

          <q-btn flat round dense icon="close" v-close-popup />
        </q-toolbar>

        <q-card-section class="q-pt-none">
          {{ textConfirmationMsg }}
        </q-card-section>

        <q-card-actions align="right" class="text-teal">
          <q-btn
            color="grey"
            :label="$t('cancel')"
            data-cy="cancel"
            v-close-popup
            @click="cancelOverlayDiv()"
          />
          <q-btn
            color="grey"
            data-cy="no"
            label="Don't ask again"
            v-close-popup
            @click="askLater()"
          />
          <q-btn
            color="grey"
            data-cy="no"
            :label="$t('re_select')"
            v-close-popup
