  <q-dialog
    v-model="display_barcode_assignment"
    @keydown.esc="display_barcode_assignment = false"
  >
    <q-card style="min-width: 320px; max-width: 1000px">
      <q-card-section>
        {{ $t('barcode_mapping_currently_reverse_order') }}
      </q-card-section>
      <q-card-section v-if="barcode_amount > 0">
        <div
          style="margin-top: 15px"
          v-for="(barcode, index) in barcode_data"
          :key="barcode"
        >
          Barcode {{ index }} : {{ barcode }}
          <q-select
            outlined
            dense
            clearable
            v-model="barcode_field_set[index]"
            :options="doc_fields"
            @update:model-value="
