  ],
  components: {
    
    Loader,
    SubGroup,
    scriptBtn,
    SubHeader,
    ScriptLogs,
    supportForm,
    autoTesting,
    DocumentLock,
    BlockSupplier,
    MessageBanner,
    SelectionPopup,
    Classification,
    AISeverityLevel,
    ImportMultiInvoice,
    IgnoreTableValidation,
    FieldsView,
    SplitDocument,
    SidebarPanel,
    SidebarActionButtons,
    ErrorDocumentView,
    InvoiceDuplicateLock,
    TfidfPreferenceControl,
    restartClassificationPopup,
