    TableOfCheckboxes,
    HorizontalSeparator,
    ExtractedTableTabPanels,
    timeSpentTimer,
    keyboardShortcutInfoBtn,
    autoAccountingBtn,
    InvoiceButtons,
    AnnotationView,
    QRCodeExtractedFields,
    TaskBtn,
    TaskList,
    UnBlockSupplier,
    NonMappedColumnsBtn,
    WarningLogs,
  },
  watch: {
    $route(to, from) {
      if (!to.hasOwnProperty('path') || !from.hasOwnProperty('path')) {
        return;
      }
      const to_route = to.path.split('/');
      const from_route = from.path.split('/');
      // match for same route name
      if (
        to_route.length > 2 &&
        from_route.length > 2 &&
        to_route[1] === from_route[1] &&
        this.get_cached_data_id != this.docId
      ) {
        window.location.reload();
      }
    },
    // BUG_FIX_8650: Watch for record.images to become available
    // When images are populated (async from API), call setImage() to display the document
    'record.images': {
      handler(newImages) {
        if (
          newImages &&
          Array.isArray(newImages) &&
          newImages.length > 0 &&
          (!this.image || this.image === '')
        ) {
          console.log(
            'record.images watcher: Images populated, calling setImage()',
            'doc_id=' + this.docId,
            'images_count=' + newImages.length,
          );
          this.setImage();
        }
      },
      deep: true,
    },
    // Fire e-document warning toasts once the document data has actually
    // loaded. { immediate: true } covers the case where data is already
    // in the store on mount; firstLoadHandled guards re-entry so each
    // component instance only emits the toasts once.
    hasApiData: {
      handler(loaded: boolean) {
        if (!loaded || this.firstLoadHandled) return;
        this.firstLoadHandled = true;
        this.showEDocWarning();
        this.showRulesWarning();
      },
      immediate: true,
    },
  },
  computed: {
    // E-document format display with country flag.
    eDocFormatDisplay(): string {
      if (!isElectronicDocument(this.record?.extraction_method)) {
        return '';
      }
      return formatEDocType(this.record?.classification?.method || '');
    },
  },
  data() {
    return {
      skipDocTypes: ['restart_in_progress', 'restarted'],
      docId: '',
      docStatus: '',
      contact: this.$t('confirm'),
      showDialog: false,
      showExportDialog: false,
      zoom_value: ref(0.6),
      showArticlePage: false,
      disableSelectionButton: true,
      loading: false,
      isTableRow: ref(false),
      shownButtonsLength: 0,
      showExpandButton: false,
      saveInstant: false,
      magnifyGlass: {} as any,
      allowedDoctypes: allowedDocTypes,
      format_warning_dismiss: {} as any,
      excluded_fields: ['fields_group'],
      account_block: '',
      error_message: '',
      currentDisplayedMessage: ref(''),
      trigger_document_lock: ref(false),
      isInvoiceDuplicate: ref(false),
      split_document: ref(false),
      headerFabIcon: ref(false),
      dropdownModel: ref(false),
      imageLoaded: ref(false),
      textConfirmation: false,
      selectMonitor: ref(false),
      doc_script_module_setting,
      approval_history,
      barcode_amount: ref(0),
      barcode_data: ref({} as any),
      display_barcode_assignment: ref(false),
      barcode_field_set: ref({} as any),
      doc_fields: ref([] as any[]),
      // E-document warning toast IDs — non-null while a toast is on screen.
      eDocToastId: null as string | number | null,
      rulesToastId: null as string | number | null,
      firstLoadHandled: false,
    };
  },
  beforeRouteLeave: async function (to: any, from: any, next: any) {
    // Before leaving this page, lets first reset everything
    this.setDataToCache();
    this.removeBordersFromRectangles();
    this.removeAllConnectionLines();
    this.removeExistingConfirmationOverlays();
    this.removeMagnifier();
    notify.dismissAll();
    this.page = 1;
    if (this.external_window) {
      this.external_window.close();
    }

    if (typeof this.format_warning_dismiss === 'function') {
      this.format_warning_dismiss();
    }
    if (to.params.id !== from.params.id) {
      // Only release the lock if the doc_id is different
      await this.releaseDocLock({ doc_id: this.record.doc_id });
    }
    this.resetDocStore(to.fullPath);
    this.resetStoreOnRouteChange();
    next();
  },
  showDialog1: function () {
    setTimeout(() => {
      this.showDialog = true;
    }, 2000);
  },
  beforeMount: function () {
    this.renderComponent = false;
    this.isExtenedPanel = false;
  },
  mounted: function () {
    this.showLoading();
    this.connectWebSocket();
    this.init();
    this.show_all_menu_btns = true;
    this.isDebugFlagHandler();
    this.is_admin = isUserAdmin();

    let doc_id = this.$route.params.id as string;
    this.getDocAnnotations(doc_id);

    window.addEventListener('resize', this.windowResize);
    document.body.addEventListener('click', this.mouseClicked, true);

    const splitter__before = $('.img-magnifier-container') as HTMLElement;
    if (splitter__before) {
      splitter__before.addEventListener('scroll', this.removeOverlayandLines);
    }

    const splitter__after = $('.q-splitter__after');
    if (splitter__after) {
      splitter__after.addEventListener('scroll', this.removeOverlayandLines);
    }

    document.addEventListener(
      'dispatch_status_bar_message',
      this.dispatchTaskbarMessage,
    );
    document.addEventListener(
      'highlight_table_row',
      this.highlightTableRowArea,
    );
    document.addEventListener('refresh_canvas', this.refreshCanvas);
    document.addEventListener(
      'set_splitter_model',
      this.setSplitterModelWrapper,
    );
    // this reference is beaing used from the child window
    (<any>window).FieldValidationView = this;
  },
  unmounted: function () {
    window.removeEventListener('resize', this.windowResize);
    window.removeEventListener('keydown', this.keydownEvent);
    document.removeEventListener(
      'dispatch_status_bar_message',
      this.dispatchTaskbarMessage,
    );
    document.removeEventListener(
      'highlight_table_row',
      this.highlightTableRowArea,
    );
    document.removeEventListener(
      'removeSelectedAreaOnImage',
      this.removeSelectedAreaOnImage,
    );

    const splitter__before = $('.img-magnifier-container') as HTMLElement;
    if (splitter__before) {
      splitter__before.removeEventListener(
        'scroll',
        this.removeOverlayandLines,
      );
    }

    const splitter__after = $('.q-splitter__after');
    if (splitter__after) {
      splitter__after.removeEventListener('scroll', this.removeOverlayandLines);
    }

    try {
      this.screenshot = $('.screenshot') as HTMLElement;
      if (this.screenshot) {
        this.screenshot.removeEventListener('dblclick', this.dblClickToSelect);
        this.screenshot.removeEventListener('pointerdown', this.startDrag);
      }
    } catch (err) {
      logError('something went wrong while unmount', err);
    }

    document.removeEventListener('refresh_canvas', this.refreshCanvas);
    document.removeEventListener(
      'set_splitter_model',
      this.setSplitterModelWrapper,
    );

    // Clean up any open warning toasts so they don't leak across pages.
    if (this.eDocToastId !== null) notify.dismiss(this.eDocToastId);
    if (this.rulesToastId !== null) notify.dismiss(this.rulesToastId);
  },
  methods: {
    // Emit the EDI-cannot-select warning toast if the record is an electronic
    // document and the user hasn't permanently dismissed it. One-shot — guarded
    // by eDocToastId so duplicate calls are no-ops.
    showEDocWarning() {
      if (this.eDocToastId !== null) return;
      if (localStorage.getItem('dismiss_edoc_warning') === 'true') return;
      if (this.record?.extraction_method !== 'ELECTRONIC_DOCUMENT') return;
      this.eDocToastId = notify.warning(i18n.t('cannot_select_on_edi') as string, {
        id: 'edi-cannot-select-warning',
        duration: Infinity,
        action: {
          label: i18n.t('dont_show_again') as string,
          onClick: () => {
            localStorage.setItem('dismiss_edoc_warning', 'true');
          },
        },
        onDismiss: () => {
          this.eDocToastId = null;
        },
      });
    },
    // Emit the "rules cannot be created" warning toast if the record has no
    // filter_values and isn't an XML invoice. Renders the support mailto via
    // a render function since vue-sonner doesn't render HTML strings.
    showRulesWarning() {
      if (this.rulesToastId !== null) return;
      if (localStorage.getItem('dismiss_rules_warning') === 'true') return;
      if (this.record?.doc_type === 'XML_INVOICE') return;
      const hasFilterValues =
        this.record?.hasOwnProperty('filter_values') && this.record?.filter_values;
      if (hasFilterValues) return;

      const LINK_OPEN = '__LINK_OPEN__';
      const LINK_CLOSE = '__LINK_CLOSE__';
      const raw = i18n.t('rules_cannot_be_created', {
        link: LINK_OPEN,
        linkEnd: LINK_CLOSE,
      }) as string;
      const [before = '', afterOpen = ''] = raw.split(LINK_OPEN);
      const [linkText = '', after = ''] = afterOpen.split(LINK_CLOSE);
      const mailto = createRulesSupportMailtoLink();
      const messageRenderer = () =>
        h('span', [
          before,
          h(
            'a',
            {
              href: mailto,
              target: '_blank',
              rel: 'noopener',
              style: 'text-decoration: underline; color: inherit;',
            },
            linkText.trim() || mailto,
          ),
          after,
        ]);
      this.rulesToastId = notify.warning(messageRenderer as unknown as string, {
        id: 'edi-rules-warning',
        duration: Infinity,
        action: {
          label: i18n.t('dont_show_again') as string,
          onClick: () => {
            localStorage.setItem('dismiss_rules_warning', 'true');
          },
        },
        onDismiss: () => {
          this.rulesToastId = null;
        },
      });
    },
    downloadFile(record?: any, docId?: string, tokenQueryParam?: string) {
      if (!docId || !tokenQueryParam) return;
      downloadDocumentFile(docId, record?.filename || '', tokenQueryParam);
    },
    prepareBarcodeData() {
      if (!this.record.hasOwnProperty('barcode_mapping')) {
        this.record.barcode_mapping = {};
      }
      this.barcode_field_set = JSON.parse(
        JSON.stringify(this.record.barcode_mapping),
      );
      this.doc_fields = [];
      this.barcode_amount = Object.keys(
        JSON.parse(JSON.stringify(this.record.barcode_data)),
      ).length;
      let barcode_list = JSON.parse(JSON.stringify(this.record.barcode_data));
      let index = 1;
      for (const [key, value] of Object.entries(barcode_list)) {
        (value as any).forEach((barcode: any) => {
          this.barcode_data[index] = barcode;
          index += 1;
        });
      }
      for (let field_info in this.formBuilderConfigModel) {
        let field = this.formBuilderConfigModel[field_info];
        if (
          field.fieldType == 'TextInput' ||
          field.fieldType == 'AmountFields'
        ) {
          if (field.hasOwnProperty('id')) {
            field['value'] = field['field_id'];
            field['label'] = this.$t(field['field_name']);
            this.doc_fields.push(field);
          }
        }
      }

      this.display_barcode_assignment = true;
    },
    setFieldData(barcode: any, field: any, index: number) {
      if (
        this.record.barcode_mapping[index] != null &&
        this.record.barcode_mapping[index] != undefined
      ) {
        let name = this.record.barcode_mapping[index].field_name;
        this.formBuilderModel[name].formatted_value = '';
        this.$refs.fieldsView.inputValueChanges(name);
      }

      if (field != null && field != undefined) {
        this.record.barcode_mapping[index] = field;
        this.formBuilderModel[field.field_name].formatted_value = barcode;
        this.$refs.fieldsView.inputValueChanges(field.field_name);
      }
    },
    dispatchTaskbarMessage(event: any) {
      if (!event.detail.message) {
        return;
      }
      this.currentDisplayedMessage = event.detail.message;
    },
    showNonMappedColumnsDialog() {
      if (this.isFormBuilderMode || this.isReadOnly) {
        return;
      }
      const event = new CustomEvent('show_non_mapped_columns_dialog', {});
      document.dispatchEvent(event);
    },
    deleteTable() {
      if (this.isFormBuilderMode || this.isReadOnly) {
        return;
      }

      this.record.tables = [];
      const event = new CustomEvent('delete_table', {});
      document.dispatchEvent(event);
    },
    addColumnInLineItems() {
      if (this.isFormBuilderMode || this.isReadOnly) {
        return;
      }
