    async getPreviousDocId(params: dynamicObj) {
      try {
        let {
          currentDocIndex,
          paginationCount,
          userPagination,
          documents,
          skip,
          query,
        } = params;
        let nextId = '';
        //if the index is >= 0 and on the page > 1 then we find previous id
        if (currentDocIndex >= 0 && paginationCount >= 1) {
          let pageCount = paginationCount;
          let index = currentDocIndex - 1;
          let foundPreviousId = false;
          //loop through the documents to find the previous id
          while (!foundPreviousId) {
            //if the index is >= 0 then we find the previous id
            if (index >= 0) {
              if (this.skipDocTypes.includes(documents[index].status)) {
                index--;
                continue;
              }
              nextId = documents[index].id;
              foundPreviousId = true;
            } else {
              //end of data so we fetch the previous page data
              if (skip <= 0) {
                break;
              }
              pageCount--;
              skip = (pageCount - 1) * userPagination;
              const response = await documentListApiService.getList(
                `?&skip=${skip as number}&limit=` + userPagination + query,
              );
              documents = response.documents;
              index = response.documents.length - 1;
            }
          }
        } else {
          //fallback if the current document index is not found
          if (documents.length > 0) {
            nextId = documents[0].id;
          }
        }
        return { nextId, skip };
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
    async getNextDocId(params: dynamicObj) {
      let {
        currentDocIndex,
        paginationCount,
        userPagination,
        totalRecord,
        totalPage,
        response,
        skip,
        query,
      } = params;
      let nextId = '';
      //if the index is >= 0 and on the page < totalPage then we find next id
      if (currentDocIndex >= 0 && paginationCount !== totalPage) {
        let documents = response.documents;
        let pageCount = paginationCount;
        let index = currentDocIndex + 1;
        let foundNextId = false;
        //loop through the documents to find the next id
        while (!foundNextId) {
          //if the index is < documents.length then we find the next id
          if (index < documents.length) {
            if (this.skipDocTypes.includes(documents[index].status)) {
              index++;
              continue;
            }
            nextId = documents[index].id;
            foundNextId = true;
          } else {
            //end of totalRecord so we break the loop
            if (skip >= totalRecord) {
              break;
            }
            //end of data so we fetch next page data
            pageCount++;
            skip = (pageCount - 1) * userPagination;
            const response = await documentListApiService.getList(
              `?&skip=${skip as number}&limit=` + userPagination + query,
            );
            documents = response.documents;
            index = 0;
          }
        }
      } else {
        //fallback if the current document index is not found
        if (response.documents.length > 0) {
          nextId = response.documents[0].id;
        }
      }
      return { nextId, skip };
    },
    async routeToNextDoc(direction: 'next' | 'prev') {
      this.showLoading();
      try {
        let query = await this.makeQueryParamFromFilters(false);

        const user_pref = await preferencesService.getAllUserPreferences();
        //load the user pagination size
        let userPagination = Number(user_pref.PAGINATION_SIZE) || 10;
        //load the current pagination count
        let paginationCount = this.getPaginationCount();
        if (!paginationCount) {
          paginationCount = 1;
        }
        //calculate the skip value
        let skip = (paginationCount - 1) * userPagination;
        const response = await documentListApiService.getList(
          `?&skip=${skip}&limit=` + userPagination + query,
        );
        let currentDocIndex = response.documents.findIndex(
          (doc: any) => doc.id === this.docId,
        );
        let totalRecord = response.overview['results-count'];
        const totalPage = Math.ceil(response.total / userPagination);
        let nextId = '';
        let nextDocResponse = { nextId: '', skip: skip };
        if (direction === 'next') {
          nextDocResponse = await this.getNextDocId({
            currentDocIndex,
            paginationCount,
            userPagination,
            totalRecord,
            totalPage,
            response,
            skip,
            query,
          });
        } else if (direction === 'prev') {
          nextDocResponse = await this.getPreviousDocId({
            currentDocIndex,
            paginationCount,
            userPagination,
            documents: response.documents,
            skip,
            query,
          });
        }
        nextId = nextDocResponse.nextId;
        skip = nextDocResponse.skip;
        if (nextId !== '' && nextId !== null) {
          notify.success(this.$t('NEXT_DOC_LOADED'));
          this.unLockDoc();
          window.removeEventListener('beforeunload', this.onTabClose);
          this.resetAllStoreData();
          const latestPageCount =
            Math.ceil(skip / userPagination) + 1;
          LocalStorage.set(getUserBasedKey(dashboard_pagination), {
            paginationCount: latestPageCount,
            pagination_size: userPagination,
          });
          this.$router.push('/field_validation_v1/' + nextId);
        } else {
          notify.error(this.$t('NO_NEXT_DOC'));
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
