        this.ai_fields =
          this.record && this.record.fields && Array.isArray(this.record.fields)
            ? this.record.fields.length
            : 0;

        let response: any;
        if (
          !this.record.filter_values ||
          !(this.record.filter_values.length > 0) ||
          !Array.isArray(this.record.filter_values)
        ) {
          return;
        }

        let query =
          '?doc_type=' +
          this.record.doc_type +
          '&filter_values=' +
          this.record.filter_values.join();

