    showConnectionFromField(connectionId: string, isTableRow = false) {
      this.isTableRow = isTableRow;

      if (this.field_view_mode === 'annotate') {
        this.showNotification(this.$t('annotation_mode_is_on_warning'));
        return;
      }

      if (this.pdf_in_window) {
        this.external_window.PdfView.removeOverlayandLines();
        this.external_window.PdfView.restrictDrawing();
      } else {
        this.removeOverlayandLines();
        this.restrictDrawing();
      }

      let fieldElement: HTMLElement = this.getElementToConnect(
        $('#' + connectionId) as HTMLElement,
      ) as HTMLElement;
      if (!fieldElement) {
        return;
      }
      let pageNumber = Number(fieldElement.getAttribute('pageno'));
      pageNumber = isNaN(pageNumber) ? this.page : pageNumber;
      const pageNumberChanged = pageNumber && pageNumber !== this.page;

      // Set the connection ID for highlighting
      this.connectionId = connectionId;

      // Set the new page and image URL if the page number has changed
      if (pageNumberChanged) {
        this.page = pageNumber;

        this.image =
          this.baseUrl +
          '/' +
          cleanUpImagePath(this.record.images[this.page - 1].path);
        if (this.pdf_in_window) {
          this.sendMessegeToChildWindow('image', this.image, true);
        }
        setTimeout(() => {
          const newRaw = $('#' + connectionId) as HTMLElement;
          if (!newRaw) return;
          const newField = this.getElementToConnect(newRaw) as HTMLElement;
          if (!newField) return;
          this.handleHighlightReact(connectionId, newField);
        }, 400);
        return;
      }

      this.handleHighlightReact(connectionId, fieldElement);
    },
    handleHighlightReact(connectionId: string, fieldElement: HTMLElement) {
      this.$nextTick(() => {
        if (this.pdf_in_window) {
          this.external_window.PdfView.proceedForReactFinding(
            connectionId,
            fieldElement,
            this.isTableRow,
          );
        } else {
          this.proceedForReactFinding(
            connectionId,
            fieldElement,
            this.isTableRow,
          );
        }
      });
    },
    proceedForReactFinding(
      connectionId: string,
      fieldElement: Element,
      isTableRow: boolean,
    ) {
      // Duplicate-coords rows share one drawn rect; resolve to it (see aiRowRectMap).
      const rectId = (this.aiRowRectMap && this.aiRowRectMap[connectionId]) || connectionId;
      let rectElement = $('#' + rectId + '_rect');

      if (rectElement) {
        this.scrollInToViewCenter(rectElement as HTMLElement);
      }

      setTimeout(() => {
        if (isTableRow) {
          this.highlightRow(rectElement);
          return;
        }

        if (!rectElement) {
          this.proceedIfReactNotFound(fieldElement);
          return;
        }
        this.showConnection(connectionId, rectElement, fieldElement);
      }, 50);
    },
    proceedIfReactNotFound(fieldElement: Element) {
      // For electronic documents, text selection is not supported
      // Warning is displayed inline in the left panel instead of as a toast
      if(this.record.extraction_method === 'ELECTRONIC_DOCUMENT'){
        return;
      }
      this.componentType = fieldElement.getAttribute('child_type') as string;

      let inputValue = '';

      if (this.componentType === 'checkbox') {
        inputValue = fieldElement.getAttribute('aria-checked') ? 'true' : '';
      } else {
        let input: HTMLInputElement | null = fieldElement.querySelector(
          this.componentType,
        );

        if (input) {
          inputValue = input.value;

          //If field is readonly, disable drawing
          const field_name = input.getAttribute('data-name');
          if (
            field_name &&
            this.formBuilderConfigModel[field_name].is_readonly
          ) {
            return;
          }
        }
      }

      if (inputValue != '') {
        let fieldTitle = '';
        const tempHeadingStr = this.getOverlayHeadings();
        if (tempHeadingStr) {
          let tempHeading = tempHeadingStr.split(splitDelimiter);
          fieldTitle = tempHeading[1];

          fieldTitle += ': ';
        }

        const strMessage =
          fieldTitle + this.$t('SELECT_AREA_NO_COORDINATES');
        this.showNotification(strMessage);
        const message_event = new CustomEvent('dispatch_status_bar_message', {
          detail: { message: this.$t('SELECT_AREA') },
        });
        document.dispatchEvent(message_event);
      } else {
        this.showNotification(this.$t('SELECT_AREA'));
        const message_event = new CustomEvent('dispatch_status_bar_message', {
          detail: { message: this.$t('SELECT_AREA') },
        });
        document.dispatchEvent(message_event);
      }

      // In read-only mode show the "not extracted / select area" message above,
      // but do not enable drawing — the user must not reselect/redraw the area.
      if (this.isReadOnly) {
        return;
      }

      if (this.pdf_in_window) {
        this.external_window.PdfView.enableDrawing();
        this.external_window.PdfView.connectionId = this.connectionId;
      } else {
        this.enableDrawing();
      }
    },

    /**
     * This connection line will perform three tasks
     * 1. Add border to rect, but we'll remove previous border first
     * 2. Add line from input to rect, but we'll remove previous line first
     * 3. Add an overlay to rect to decide whether co-ordinates are correct or not
     * @param ev
     */
    showConnection(connectionId: string, rectElement: any, fieldElement: any) {
      if (this.pdf_in_window) {
        this.external_window.PdfView.proceedForReactFinding(
          connectionId,
          fieldElement,
          false,
        );
        return;
      }
      if (rectElement && fieldElement) {
        this.drawOverlay(connectionId, rectElement);
        // Adding border to corresponding rectangle
        rectElement.classList.add('svg-stroke-border');

        // Drawling line
        this.connect(
          rectElement as HTMLElement,
          fieldElement as HTMLElement,
          '#26a69a',
          2,
        );
      } else {
        alert(this.$t('NO_MAPPING_AVAILABLE'));
      }
    },

    /**
     * Replace new overlay with the old one
     */
    saveOverlayResult() {
      this.cleanRectangles();
      if (this.pdf_in_window) {
        this.external_window.PdfView.redraw();
      } else {
        this.redraw();
      }
      this.getTextByCoordinates(this.rectCordinate);
    },
    /**
     *
     * @param element1
     * @param element2
     * @param color
     * @param thickness
     */
    connect(
      element1: HTMLElement,
      element2: HTMLElement,
      color: string,
      thickness: number,
    ) {
      // draw a line connecting elements
      const off1 = this.getOffset(element1);
      const off2 = this.getOffset(element2);
      // bottom right
      const x1 = off1.left;
      const y1 = off1.top + off1.height / 2;
      // top right
      const x2 = off2.right;
      const y2 = off2.top + off2.height / 2;
      // distance
      const length = Math.sqrt((x2 - x1) * (x2 - x1) + (y2 - y1) * (y2 - y1));
      // center
      const cx = (x1 + x2) / 2 - length / 2;
      const cy = (y1 + y2) / 2 - thickness / 2;
      // angle
      const angle = Math.atan2(y1 - y2, x1 - x2) * (180 / Math.PI);
      // Before adding line from selected record to input, lets first remove previous line
      this.removeAllConnectionLines();
      // Drawing new line
      const line = document.createElement('div');
      line.setAttribute('id', 'connection_line');
      line.style.cssText =
        'z-index: 102;padding:0px; margin:0px; height:' +
        thickness +
        'px; background-color:' +
        color +
        '; line-height:1px; position:absolute; left:' +
        cx +
        'px; top:' +
        cy +
        'px; width:' +
        length +
        'px; -moz-transform:rotate(' +
        angle +
        'deg); -webkit-transform:rotate(' +
        angle +
        'deg); -o-transform:rotate(' +
        angle +
        'deg); -ms-transform:rotate(' +
        angle +
        'deg); transform:rotate(' +
        angle +
        'deg);';
      document.body.appendChild(line);
    },
    async getTextByCoordinates(cordinates: RectCoordinateType) {
      const data = this.record;
      let formData = new FormData();

      let x1 = cordinates.startX / this.imageWidth;
      let y1 = cordinates.startY / this.imageHeight;
      let x2 = cordinates.endX / this.imageWidth;
      let y2 = cordinates.endY / this.imageHeight;

      formData.append('x0', x1.toString());
      formData.append('y0', y1.toString());
      formData.append('x1', x2.toString());
      formData.append('y1', y2.toString());

      formData.append('doc_id', data.doc_id);
      formData.append('page', this.page.toString());
      formData.append('field_name', this.connectionId);

      if (
        this.formBuilderConfigModel[this.connectionId].hasOwnProperty(
          'parent_field_name',
        )
      ) {
        formData.append(
          'parent_field_name',
          this.formBuilderConfigModel[this.connectionId].parent_field_name,
        );
      }

      // formData.append('image_base64', data.images[page - 1].content);
      this.showLoading();

      let response: any;
      try {
        response = await documentDetailApiService.get_field_value(formData);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }

      this.textApiResponse = response;

      const coords = response.coords;

      if (
        !coords ||
        (coords[0].x === 0 &&
          coords[0].y === 0 &&
          response.formatted_value === '')
      ) {
        notify.error(
          this.$t('EMPTY_MAPPING_NOT_ALLOWED'),
        );
        if (this.pdf_in_window) {
          this.external_window.PdfView.prepareRectangles();
          this.external_window.PdfView.enableDrawing();
        } else {
          this.prepareRectangles();
          this.enableDrawing();
        }
        return;
      }

      // TODO only for invoices
      if (this.record.doc_type == 'INVOICE') {
        if (this.dontAsk) {
          if (this.textApiResponse.multi_line) {
            this.textConfirmationMsg = this.$t('is_multi_line_confirm');
          } else {
            this.textConfirmationMsg = this.$t('is_draw_correct');
          }
          this.textConfirmation = true;
        } else {
          this.saveInstant = true;
        }
      } else {
        this.updateFieldData();
      }
    },

    updateFieldData() {
      this.$refs['fieldsView'].updateFieldData(this.textApiResponse);
      this.saveInstant = false;
      this.textApiResponse = null;
    },

