<template>
    <template
        v-if="record.warnings && record.warnings.length > 0">
        <span class="footer-status-message text-red cursor-pointer"
        @click="openWarningsBox($event)">
        <div class="row flex-smart items-center" style="gap: 4px;">
            <Icon icon="mdi:alert" width="26" height="26" />
            <span style="color: orange; font-weight: 500;margin-left: 10px;">
                {{ $t('warning_in_document_script') }}
            </span>
        </div>
        <!-- <q-icon src="/images/warnung-triangle.svg" >{{ record.warnings.length }}</q-icon> -->
        </span>
        <q-separator vertical class="q-mx-md"/>
    </template>

      <!-- document Warning Logs -->
        <q-dialog
            v-model="display_doc_warning_logs"
            transition-show="slide-up"
            transition-hide="slide-down"
            :transition-duration="0"
            class="transparent-backdrop"
        >
            <q-card :style="{ position: 'fixed', bottom: '60px', left: left + 'px' }" class="warning-box">
                <q-toolbar class="text-white secondary-toolbar compact-toolbar">
                    <Icon icon="mdi:alert" width="22" height="22" />
                    <q-toolbar-title >
                        <span style="font-weight: 500; font-size: 14px;">{{ $t('doc_warning_logs') }}</span>
                    </q-toolbar-title>
                    <q-btn flat round dense icon="close" v-close-popup size="sm" />
                </q-toolbar>
                <q-card-section class="warning-content">
                    <div>
                        <template v-for="(msg, index) in (record.warnings as any[])" :key="index">
                            <div class="warning-entry">
                                <div class="warning-message-text" v-html="msg.message"></div>
                                <q-btn-dropdown
                                    v-if="msg.code === 'DOCUMENT_TRIMMED'"
                                    :label="$t('process_more')"
                                    no-caps
                                    unelevated
                                    dense
                                    class="process-more-btn"
                                    :style="{ backgroundColor: orgColor, color: 'white' }"
                                >
                                    <q-list class="process-more-menu">
                                        <q-item class="first-x-pages-item">
                                            <q-item-section>
                                                <div class="first-x-label">{{ $t('first_x_pages') }}</div>
                                                <div class="first-x-input-row">
                                                    <q-input
                                                        v-model="firstXPages"
                                                        type="number"
                                                        dense
                                                        outlined
                                                        class="pages-input"
                                                        :min="1"
                                                        :max="msg.total_pages"
                                                    />
                                                    <q-btn
                                                        unelevated
                                                        no-caps
                                                        dense
                                                        label="Go"
                                                        class="go-btn"
                                                        :style="{ backgroundColor: orgColor, color: 'white' }"
                                                        @click="processMorePages(msg, false)"
                                                    />
                                                </div>
                                            </q-item-section>
                                        </q-item>
                                        <q-separator />
                                        <q-item clickable v-close-popup @click="processMorePages(msg, true)" dense class="all-pages-item">
                                            <q-item-section>
                                                <div class="all-pages-row">
                                                    <q-icon name="description" :style="{ color: orgColor }" size="18px" />
                                                    <span>{{ $t('all') }} {{ msg.data?.original_page_count }} {{ $t('pages') }}</span>
                                                </div>
                                            </q-item-section>
                                        </q-item>
                                    </q-list>
                                </q-btn-dropdown>
                            </div>
                        </template>
                    </div>
                </q-card-section>
            </q-card>
        </q-dialog>
    <!-- END Warning document -->
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref, computed } from 'vue';

import { storeToRefs } from 'pinia';
import { useDocumentStore, useSettingStore } from 'src/store/main';
import { documentDetailApiService } from 'src/services';
import { getOrgId } from 'src/utils/organization/org_id_helper';
export default defineComponent({
  el: '#app',
  components: {
    
  },
  data () {
    return {
      left: 0,
      firstXPages: 6,
      loading: false
    }
  },
  setup() {
    const doc_store = useDocumentStore();
    const { record } = storeToRefs(doc_store);

    const settings_store = useSettingStore();
    const { user_settings } = storeToRefs(settings_store);

    const orgColor = computed(() => user_settings.value?.['ORG_COLOR_PREFERENCE'] || '#1976d2');

    return {
      record,
      doc_store,
      user_settings,
      orgColor,
      display_doc_warning_logs: ref(false),
    };
  },

  methods: {
    openWarningsBox(event: any) {
        const rect = event.target.getBoundingClientRect()

        // Calculate the left position for the dialog
        this.left = rect.left - 60
        this.display_doc_warning_logs = true;
    },
    async processMorePages(msg: any, processAll: boolean = false) {
        const pagesToProcess = processAll ? 'all' : this.firstXPages;

        const data: Record<string, any> = {
            org_id: getOrgId(),
            pages_to_process: String(pagesToProcess),
        };

        // Add optional fields if available
        if (this.record.doc_type) {
            data.doc_type = this.record.doc_type;
        }
        if (this.record.sub_doc_type) {
            data.sub_doc_type = this.record.sub_doc_type;
        }
        if (this.record.doc_origin) {
            data.doc_origin = this.record.doc_origin;
        }
        if (this.record.doc_language) {
            data.doc_language = this.record.doc_language;
        }
        if (this.record.doc_locale) {
            data.doc_locale = this.record.doc_locale;
        }
        if (this.record.doc_classification_label) {
            data.doc_classification_label = this.record.doc_classification_label;
        }

        try {
            this.loading = true;
            await documentDetailApiService.restartClassification(data, this.record.doc_id);
            notify.success(this.$t('NEW_CLASSIFICATION'));
            this.display_doc_warning_logs = false;
            // Redirect to dashboard
            this.$router.push('/dashboard');
        } catch (error: any) {
            logError(error);
            notify.error(error?.message || this.$t('error_restarting_with_classification'));
        } finally {
            this.loading = false;
        }
    },
  },
});
</script>
