<template>

<q-list dense>
  <q-item >
    <q-item-section>
      <f-toggle v-model="tfidf_setting[use_etext_if_available]" size="sm" :disable="isReadOnly" @update:model-value="showConfirmDialog(use_etext_if_available)" :label="$t('ocr_setting_etext')"/>
    </q-item-section>
  </q-item>

  <q-item >
    <q-item-section class="q-pb-sm">
      <q-select outlined dense emit-value map-options :label="$t('ai_model')" :readonly="isReadOnly"
      v-model="tfidf_setting[ai_model_key]" :options="aiModelList" @update:model-value="showConfirmDialog(ai_model_key)" />
    </q-item-section>
  </q-item>
</q-list>

 
  <q-dialog v-model="confirmRestart" persistent>
    <q-card>
      <q-card-section
        class="row"
        style="justify-content: center; display: flex"
      >
        <q-avatar icon="warning" color="primary" />
      </q-card-section>

      <q-card-section class="row items-center">
        <span class="q-ml-sm"> {{ $t('document_must_be_restarted_change_take_effect') }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn appearance="cancel" data-cy="cancel" :label="$t('cancel')" v-close-popup @click="cancel()"/>
        <f-btn :label="$t('confirm')" data-cy="delete-popup" v-close-popup @click="saveSettingsAndRestart()" />
      </q-card-actions>
    </q-card>
  </q-dialog>

</template>

<script lang='ts'>

import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { userApiService } from 'src/services';
import type { dynamicObj } from 'src/pages/assets';
import { useFormBuilderStore } from 'src/store/main';
import { ApiExceptions } from 'src/exceptions/index';
import { CONSTANTS, aiModelList } from 'src/constants';
import { notify } from 'src/components/notifications/notify';

export default defineComponent({
  name: 'TfidPreference',
    emits: ['restartDocument'],
  props: {
    tfidf_id: {
      type: String,
      default: ''
    },
    docId: {
      type: String,
      default: ''
    },
    isReadOnly: {
      type: Boolean,
      default: false
    },
  },
  data() {
    return {
      selectedKey: ref(''),
      confirmRestart: ref(false),
      tfidf_setting: ref({} as any),
      tfidf_setting_copy: ref({} as any),
      ai_model_key: CONSTANTS.ai_model,
      use_etext_if_available: CONSTANTS.use_etext_if_available,
      aiModelList: aiModelList,
    };
  },
  mounted: function () {
    this.setDefaultValues();
    this.getTfidfPreference(this.use_etext_if_available);
    this.getTfidfPreference(this.ai_model_key);
  },
  methods: {
    setDefaultValues() {
      this.tfidf_setting = {
        [this.use_etext_if_available]: false,
        [this.ai_model_key]: CONSTANTS.DEFAULT_AI_MODEL,
      }

      this.tfidf_setting_copy = JSON.parse(JSON.stringify(this.tfidf_setting));
    },
    async getTfidfPreference(key: string) {
      try {
        let res = await userApiService.getTfidfPreference(key, this.tfidf_id);
        this.setSetting(key, res);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
    setSetting (key: string, value: any) {

      // For Boolean
      if (typeof value === 'string') {
        const lowercase_value = value.toLowerCase();
        if (lowercase_value === 'true' || lowercase_value === 'false') {
          this.tfidf_setting[key] = lowercase_value === 'true';
          this.tfidf_setting_copy[key] = this.tfidf_setting[key];
          return;
        }
      }

      this.tfidf_setting[key] = value;
      this.tfidf_setting_copy[key] = value;
    },
    async saveSettings() {
      try {

        const supplierId = this.formBuilderModel['supplier_id']?.formatted_value ?? '';
        
        const formData = new FormData();
        formData.append('key', this.selectedKey);
        formData.append('value', this.tfidf_setting[this.selectedKey].toString());
        formData.append('tfidf_id', this.tfidf_id);
        formData.append('supplier_id', supplierId );

        const response = await userApiService.setTfidfPreference(formData);

        this.tfidf_setting_copy[this.selectedKey] = this.tfidf_setting[this.selectedKey]
        
        notify.success(this.$t('MSG_SAVE'));
      } catch (err) {
        this.tfidf_setting[this.selectedKey] = this.tfidf_setting_copy[this.selectedKey]

        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.selectedKey = ''
      }

    },
    async saveSettingsAndRestart() {
      this.confirmRestart = false;
      await this.saveSettings();
      this.$emit('restartDocument', this.docId);

    },
    cancel() {
      this.confirmRestart = false;
      // revert change
      this.tfidf_setting[this.selectedKey] = this.tfidf_setting_copy[this.selectedKey]
    },
    showConfirmDialog(key: string) {
      this.confirmRestart = true;
      this.selectedKey = key;
    },
  },
  setup() {

    const form_builder_store = useFormBuilderStore();
    const { formBuilderModel} = storeToRefs(form_builder_store);
    return {
      formBuilderModel,
    };
  }
});
</script>
