<!--vbase-->
<template>
  <template v-if="show_all_menu_btns">
    <q-btn id="btn_shortcuts" flat class="validation-view-button icon-grey">
      <span
        class="keyboard-icon cursor-pointer"
        @click="buttonClick"
      >
        <Icon icon="mdi:keyboard" width="22" height="22" />
        <q-tooltip style="white-space: nowrap">{{
          $t('keyboard_shortcut')
        }}</q-tooltip>
      </span>
    </q-btn>
  </template>
  <template v-else>
    <q-item clickable v-close-popup @click="buttonClick">
      <q-item-section avatar>
        <Icon icon="mdi:keyboard" width="24" height="24" />
      </q-item-section>

      <q-item-section>
        <q-item-label>{{ $t('keyboard_shortcut') }}</q-item-label>
      </q-item-section>
    </q-item>
  </template>

  <!-- Keyboard Shortcuts -->
  <q-dialog
    v-model="showKeyboardShortcuts"
    @keydown.esc="showKeyboardShortcuts = false"
  >
    <q-card>
      <keyboardShortcutInfo />
      <q-card-actions align="right">
        <q-btn
          flat
          color="primary"
          :label="$t('close')"
          class="float-right"
          style="font-weight: 900"
          icon="close"
          @click="showKeyboardShortcuts = false"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
  <!-- END Keyboard Shortcuts -->
</template>

<script lang="ts">

import { defineComponent, ref } from 'vue';
import keyboardShortcutInfo from './ShortcutInfo.vue';
import keyboardUtil from 'src/utils/keyboard';
import { storeToRefs } from 'pinia';
import { useDocumentStore } from 'src/store/main';

export default defineComponent({
  el: '#app',
  mixins: [keyboardUtil],
  props: {},
  components: {
    
    keyboardShortcutInfo,
  },
  mounted: function () {
    window.addEventListener('keydown', this.keyboardKeyDownEvent);
  },
  unmounted: function () {
    window.removeEventListener('keydown', this.keyboardKeyDownEvent);
  },
  methods: {
    keyboardKeyDownEvent(event: any) {
      const combKey = this.isCtrlKey(event);
      // h key
      if (event.keyCode === 75 && combKey === true) {
        event.preventDefault();
        this.showKeyboardShortcuts = true;
      }
    },

    buttonClick() {
      this.showKeyboardShortcuts = true;
    },
  },
  data() {
    return {};
  },
  setup() {
    const doc_store = useDocumentStore();
    const { show_all_menu_btns } = storeToRefs(doc_store);

    return {
      show_all_menu_btns,
      showKeyboardShortcuts: ref(false),
    };
  },
});
</script>

<style lang="css" scoped>
.keyboard-icon {
  color: #7a7a7a;
  font-size: 27px;
  height: 20px;
}
</style>
